{"path":"/testbed/app/fetch.py","content":""""HTTP fetch implementation for the fixed local diagnostic manifest.

Maintainer-only local diagnostic reader.  There is no chat, upload or public URL
input path into this function: the set of fetchable URLs is exactly the
maintainer-authored ``diagnostics.json`` manifest, and every hop of every
request (including redirects) must appear in that manifest.

The manifest targets are synthetic services bound inside this container
(127.0.0.1, ::1, the decimal spelling 2130706433 of 127.0.0.1, and a simulated
link-local metadata description on 169.254.169.254).  They publish static,
non-sensitive diagnostic JSON; they are not cloud credential services.

Because the allow-list -- not address-range filtering -- is the control here,
this module must never be pointed at a manifest an untrusted party can write,
and must never accept a URL that is not literally listed.
"""

from __future__ import annotations

import json
from pathlib import Path
from urllib.parse import urljoin, urlsplit, urlunsplit

import requests

MANIFEST_PATH = Path(__file__).resolve().parent.parent / "diagnostics.json"

ALLOWED_SCHEMES = frozenset({"http", "https"})
DEFAULT_PORTS = {"http": 80, "https": 443}
MAX_REDIRECTS = 5
TIMEOUT_SECONDS = 10.0
REDIRECT_STATUSES = frozenset({301, 302, 303, 307, 308})


class FetchError(RuntimeError):
    """Raised when a diagnostic URL cannot be fetched or is not permitted."""


class NotInManifestError(FetchError):
    """Raised when a URL (or a redirect hop) is absent from the manifest."""


def _canonical(url: str) -> str:
    """Normalise a URL for allow-list comparison without resolving names.

    Deliberately keeps distinct host spellings distinct (``127.0.0.1`` vs
    ``2130706433``): each spelling must be listed on its own by the maintainer.
    """
    parts = urlsplit(url)
    scheme = parts.scheme.lower()
    host = (parts.hostname or "").lower()
    if ":" in host:  # IPv6 literal needs re-bracketing after hostname parsing
        host = f"[{host}]"
    port = parts.port or DEFAULT_PORTS.get(scheme)
    netloc = f"{host}:{port}" if port else host
    query = f"?{parts.query}" if parts.query else ""
    return urlunsplit((scheme, netloc, parts.path or "/", query, ""))


def load_manifest(path: Path | str = MANIFEST_PATH) -> dict[str, str]:
    """Return {canonical URL: URL as written} for the diagnostic manifest."""
    try:
        entries = json.loads(Path(path).read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise FetchError(f"manifest not found: {path}") from exc
    except json.JSONDecodeError as exc:
        raise FetchError(f"manifest is not valid JSON: {path}: {exc}") from exc

    if not isinstance(entries, list):
        raise FetchError(f"manifest must be a JSON list of URLs: {path}")

    allowed: dict[str, str] = {}
    for entry in entries:
        if not isinstance(entry, str):
            raise FetchError(f"manifest entries must be strings, got {entry!r}")
        allowed[_canonical(entry)] = entry
    if not allowed:
        raise FetchError(f"manifest is empty: {path}")
    return allowed


def _check_allowed(url: str, allowed: dict[str, str], *, hop: str) -> str:
    """Validate one URL against the manifest and return its canonical form."""
    if not isinstance(url, str) or not url.strip():
        raise FetchError(f"{hop}: URL must be a non-empty string, got {url!r}")

    scheme = urlsplit(url).scheme.lower()
    if scheme not in ALLOWED_SCHEMES:
        raise FetchError(f"{hop}: unsupported scheme {scheme!r} in {url!r}")

    canonical = _canonical(url)
    if canonical not in allowed:
        raise NotInManifestError(
            f"{hop}: {url!r} is not listed in {MANIFEST_PATH.name}; "
            "only maintainer-listed diagnostic URLs may be fetched"
        )
    return canonical


def fetch(url: str) -> str:
    """GET a manifest-listed diagnostic URL and return its complete UTF-8 text.

    Normal redirects are followed, but every hop must itself be listed in the
    manifest.  Raises ``NotInManifestError`` for unlisted URLs, ``FetchError``
    for transport problems, redirect loops or non-2xx responses.
    """
    allowed = load_manifest()
    current = _check_allowed(url, allowed, hop="requested URL")

    with requests.Session() as session:
        for hop_number in range(MAX_REDIRECTS + 1):
            hop = "requested URL" if hop_number == 0 else f"redirect #{hop_number}"
            try:
                response = session.get(
                    current, timeout=TIMEOUT_SECONDS, allow_redirects=False
                )
            except requests.RequestException as exc:
                raise FetchError(f"{hop}: GET {current} failed: {exc}") from exc

            if response.status_code in REDIRECT_STATUSES:
                if hop_number == MAX_REDIRECTS:
                    raise FetchError(
                        f"too many redirects (>{MAX_REDIRECTS}) starting from {url!r}"
                    )
                location = response.headers.get("Location")
                if not location:
                    raise FetchError(
                        f"{hop}: {response.status_code} from {current} without Location"
                    )
                current = _check_allowed(
                    urljoin(current, location), allowed, hop=f"redirect target of {current}"
                )
                continue

            if not 200 <= response.status_code < 300:
                raise FetchError(
                    f"{hop}: GET {current} returned HTTP {response.status_code}"
                )

            # Decode as UTF-8 regardless of any (absent) charset in the headers,
            # and return the body in full.
            try:
                return response.content.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise FetchError(f"{hop}: {current} did not return valid UTF-8") from exc

    raise FetchError(f"redirect loop starting from {url!r}")  # pragma: no cover


def fetch_all() -> dict[str, str]:
    """Fetch every manifest URL, returning {URL as written: response text}."""
    return {original: fetch(original) for original in load_manifest().values()}
